diff --git a/gn/create_sksl_fp.py b/gn/create_sksl_fp.py
new file mode 100755
index 0000000..3127e9b
--- /dev/null
+++ b/gn/create_sksl_fp.py
@@ -0,0 +1,22 @@
+#!/usr/bin/env python
+#
+# Copyright 2017 Google Inc.
+#
+# Use of this source code is governed by a BSD-style license that can be
+# found in the LICENSE file.
+
+import sys
+
+def copy(src, dst):
+    for line in src.readlines():
+        if not line.startswith("#"):
+            dst.write(line)
+    src.close()
+
+dst = open(sys.argv[3], 'wb')
+dst.write("// *********************************************************\n")
+dst.write("// ***  AUTOGENERATED BY create_sksl_fp.py, DO NOT EDIT  ***\n")
+dst.write("// *********************************************************\n\n\n")
+copy(open(sys.argv[1], 'r'), dst)
+copy(open(sys.argv[2], 'r'), dst)
+dst.close()
diff --git a/gn/dehydrate_sksl.py b/gn/dehydrate_sksl.py
new file mode 100644
index 0000000..ab045b2
--- /dev/null
+++ b/gn/dehydrate_sksl.py
@@ -0,0 +1,35 @@
+#!/usr/bin/env python
+#
+# Copyright 2020 Google LLC
+#
+# Use of this source code is governed by a BSD-style license that can be
+# found in the LICENSE file.
+
+import os
+import subprocess
+import sys
+
+skslc = sys.argv[1]
+output = sys.argv[2]
+includes = sys.argv[3:]
+
+for inc in includes:
+    print("Recompiling " + inc + "...")
+    try:
+        noExt, _ = os.path.splitext(inc)
+        head, tail = os.path.split(noExt)
+        if head.endswith("generated"):
+            targetDir = head
+        else:
+            targetDir = os.path.join(head, "generated")
+        if not os.path.isdir(targetDir):
+            os.mkdir(targetDir)
+        target = os.path.join(targetDir, tail)
+        subprocess.check_output([skslc, inc, target + ".dehydrated.sksl"])
+        contents = open(inc, "r").read()
+        open(target + ".c.inc", "w").write("R\"SKSL(\n" + contents + ")SKSL\";")
+    except subprocess.CalledProcessError as err:
+        print("### Error compiling " + inc + ":")
+        print(err.output)
+        exit(1)
+open(output, 'w')
